let currentLang = 'en';
localStorage.setItem('lang', 'en');

function updateDOM() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[currentLang] && translations[currentLang][key]) {
            const tag = el.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA') {
                el.placeholder = translations[currentLang][key];
            } else {
                el.innerHTML = translations[currentLang][key];
            }
        }
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (translations[currentLang] && translations[currentLang][key]) {
            el.placeholder = translations[currentLang][key];
        }
    });
    // Update gallery overlay titles that use data-title/data-title-es on the parent hex-item
    // (items without a data-i18n key on the title span — e.g. VLIR 2025 batch)
    document.querySelectorAll('.hex-item').forEach(item => {
        const titleEl = item.querySelector('.hex-ov-title');
        if (titleEl && !titleEl.getAttribute('data-i18n') && item.dataset.title) {
            titleEl.textContent = currentLang === 'es'
                ? (item.dataset.titleEs || item.dataset.title)
                : item.dataset.title;
        }
    });
    const langBtn = document.querySelector('.lang-btn');
    if (langBtn) {
        langBtn.innerText = currentLang === 'en' ? 'EN' : 'ES';
    }
    document.documentElement.lang = currentLang;
    document.documentElement.style.visibility = '';
}

function switchLanguage() {
    currentLang = currentLang === 'en' ? 'es' : 'en';
    localStorage.setItem('lang', currentLang);
    updateDOM();
}

function toggleNav() {
    document.getElementById('mobileNav').classList.toggle('open');
}

function toggleTheme() {
    var d = document.body.classList.toggle('dark-theme');
    localStorage.setItem('theme', d ? 'dark' : 'light');
}

(function () {
    if (localStorage.getItem('theme') === 'dark') {
        document.body.classList.add('dark-theme');
    }
})();

document.addEventListener('DOMContentLoaded', function () {
    try {
        updateDOM();
    } catch (err) {
        console.error('[idioma.js] updateDOM() failed — forcing page visibility:', err);
        document.documentElement.style.visibility = '';
    }
});
